package com.masalewala.api.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.util.*;
@Service public class JwtService{private final byte[] secret;public JwtService(@Value("${app.jwt-secret}") String secret){this.secret=secret.getBytes(StandardCharsets.UTF_8);}public String create(String email,Collection<String> roles){return Jwts.builder().subject(email).claim("roles",roles).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+86400000)).signWith(Keys.hmacShaKeyFor(secret)).compact();}public String subject(String token){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret)).build().parseSignedClaims(token).getPayload().getSubject();}}
